pytestmark = pytest.mark.django_db
S = Placement.Status


def _fields(period, **overrides):
    data = {
        "role_title": "Intern",
        "department": "IT",
        "task_description": "Build tools.",
        "start_date": period.start_date + timedelta(days=7),
        "end_date": period.end_date - timedelta(days=7),
        "proposed_supervisor_name": "Jane",
        "proposed_supervisor_email": "jane@acme.example",
    }
    data.update(overrides)
    return data


def _listen(signal):
    received = []

    def handler(sender, **payload):
        received.append(payload)

    signal.connect(handler)
    return received, handler


def test_student_creates_own_draft(student):
    period, organization = PeriodFactory(), OrganizationFactory()
    placement = PlacementService.create_draft(
        actor=student, period=period, organization=organization, **_fields(period)
    )
    assert placement.status == S.DRAFT
    assert placement.student_id == student.id


def test_coordinator_creates_for_a_student_but_needs_one(coordinator, student):
    period, organization = PeriodFactory(), OrganizationFactory()
    placement = PlacementService.create_draft(
        actor=coordinator,
        student=student,
        period=period,
        organization=organization,
        **_fields(period),
    )
    assert placement.student_id == student.id
    with pytest.raises(RuleViolation):
        PlacementService.create_draft(
            actor=coordinator, period=period, organization=organization, **_fields(period)
        )


