def test_dates_must_lie_inside_the_period(student):
    period = PeriodFactory()
    bad = _fields(period, end_date=period.end_date + timedelta(days=1))
    with pytest.raises(RuleViolation) as error:
        PlacementService.create_draft(
            actor=student, period=period, organization=OrganizationFactory(), **bad
        )
    assert error.value.code == "dates_outside_period"


