def test_submit_lists_missing_details():
    placement = PlacementFactory(role_title="", task_description="")
    with pytest.raises(RuleViolation) as error:
        PlacementService.submit(actor=placement.student, placement=placement)
    assert set(error.value.details["missing"]) == {"role_title", "task_description"}


def test_submit_moves_to_submitted_and_emits_event(django_capture_on_commit_callbacks):
    placement = PlacementFactory()
    received, handler = _listen(events.placement_submitted)
    try:
        with django_capture_on_commit_callbacks(execute=True):
            PlacementService.submit(actor=placement.student, placement=placement)
    finally:
        events.placement_submitted.disconnect(handler)
    placement.refresh_from_db()
    assert placement.status == S.SUBMITTED
    assert placement.submitted_at is not None
    assert received[0]["placement_id"] == placement.id


def test_cannot_submit_twice_or_for_another_student():
    placement = PlacementFactory()
    PlacementService.submit(actor=placement.student, placement=placement)
    with pytest.raises(InvalidTransition):
        PlacementService.submit(actor=placement.student, placement=placement)
    other = PlacementFactory()
    with pytest.raises(NotAllowed):
        PlacementService.submit(actor=StudentFactory(), placement=other)


def test_approve_with_existing_workplace_supervisor(coordinator, academic_supervisor):
    placement = SubmittedPlacementFactory(organization__is_verified=False)
    workplace = WorkplaceSupervisorFactory()
    PlacementService.approve(
        actor=coordinator,
        placement=placement,
        academic_supervisor_id=academic_supervisor.id,
        workplace_supervisor_id=workplace.id,
        remarks="Welcome",
    )
    placement.refresh_from_db()
    assert placement.status == S.APPROVED
    assert placement.workplace_supervisor_id == workplace.id
    assert placement.academic_supervisor_id == academic_supervisor.id
    assert placement.coordinator_remarks == "Welcome"
    assert placement.organization.is_verified


def test_approve_can_invite_the_proposed_supervisor(
    coordinator, academic_supervisor, django_capture_on_commit_callbacks, mailoutbox
):
    placement = SubmittedPlacementFactory(proposed_supervisor_email="boss@acme.example")
    with django_capture_on_commit_callbacks(execute=True):
        PlacementService.approve(
            actor=coordinator,
            placement=placement,
            academic_supervisor_id=academic_supervisor.id,
            invite_workplace_supervisor=True,
        )
    placement.refresh_from_db()
    assert placement.workplace_supervisor.email == "boss@acme.example"
    assert placement.workplace_supervisor.role == Role.WORKPLACE_SUPERVISOR
    assert len(mailoutbox) == 1


