def test_return_needs_remarks_then_student_edits_and_resubmits(coordinator):
    placement = SubmittedPlacementFactory()
    with pytest.raises(RuleViolation):
        PlacementService.return_for_changes(actor=coordinator, placement=placement, remarks=" ")
    PlacementService.return_for_changes(
        actor=coordinator, placement=placement, remarks="Name the supervisor."
    )
    assert placement.status == S.RETURNED
    PlacementService.update(
        actor=placement.student, placement=placement, proposed_supervisor_name="Joan Boss"
    )
    PlacementService.submit(actor=placement.student, placement=placement)
    assert placement.status == S.SUBMITTED


