def test_assign_supervisors_complete_and_terminate(coordinator):
    from apps.placements.tests.factories import ApprovedPlacementFactory

    placement = ApprovedPlacementFactory()
    new_academic = AcademicSupervisorFactory()
    PlacementService.assign_supervisors(
        actor=coordinator, placement=placement, academic_supervisor_id=new_academic.id
    )
    assert placement.academic_supervisor_id == new_academic.id
    PlacementService.complete(actor=coordinator, placement=placement)
    assert placement.status == S.COMPLETED
    other = ApprovedPlacementFactory()
    PlacementService.terminate(actor=coordinator, placement=other, reason="Left the company.")
    assert other.status == S.TERMINATED


