def test_grade_bands_validation(coordinator):
    period = PeriodFactory()
    bands = PeriodService.set_grade_bands(
        period, [{"min_percent": "70", "label": "A"}, {"min_percent": "0", "label": "F"}]
    )
    assert [band.label for band in bands] == ["A", "F"]
    with pytest.raises(RuleViolation) as error:
        PeriodService.set_grade_bands(period, [{"min_percent": "70", "label": "A"}])
    assert error.value.code == "band_zero_missing"
    with pytest.raises(RuleViolation):
        PeriodService.set_grade_bands(
            period, [{"min_percent": "0", "label": "A"}, {"min_percent": "0", "label": "B"}]
        )


def test_student_can_edit_only_own_unverified_organization(student, coordinator):
    organization = OrganizationService.create(actor=student, name="Startup", county="Nairobi")
    assert not organization.is_verified
    OrganizationService.update(actor=student, organization=organization, county="Mombasa")
    OrganizationService.verify(actor=coordinator, organization=organization)
    with pytest.raises(NotAllowed):
        OrganizationService.update(actor=student, organization=organization, county="Kisumu")
